// The master reverb: the reverb send convolved with the stereo impulse
// response of a concert hall (assets/reverb/hall.wav, generated by
// scripts/reverb/hall.py). Renders are offline, so the whole send is
// convolved at once with uniformly partitioned FFT convolution.
import { readFileSync } from 'node:fs';
import { parseWav, resample } from './pcm.js';

const HALL = new URL('../../assets/reverb/hall.wav', import.meta.url);
const BLOCK = 16384, SIZE = BLOCK * 2;

// --- radix-2 complex FFT, in place ------------------------------------------------------------

const tables = new Map();
function table(n) {
  if (!tables.has(n)) {
    const bits = Math.log2(n), reverse = new Uint32Array(n), cos = new Float64Array(n / 2), sin = new Float64Array(n / 2);
    for (let i = 0; i < n; i++) {
      let r = 0;
      for (let b = 0; b < bits; b++) r = (r << 1) | ((i >>> b) & 1);
      reverse[i] = r;
    }
    for (let i = 0; i < n / 2; i++) { cos[i] = Math.cos(2 * Math.PI * i / n); sin[i] = Math.sin(2 * Math.PI * i / n); }
    tables.set(n, { reverse, cos, sin });
  }
  return tables.get(n);
}

/** In-place FFT of (re, im); inverse = true computes the unscaled inverse. */
export function fft(re, im, inverse = false) {
  const n = re.length, { reverse, cos, sin } = table(n), sign = inverse ? 1 : -1;
  for (let i = 0; i < n; i++) {
    const j = reverse[i];
    if (j > i) {
      let t = re[i]; re[i] = re[j]; re[j] = t;
      t = im[i]; im[i] = im[j]; im[j] = t;
    }
  }
  for (let size = 2; size <= n; size <<= 1) {
    const half = size >> 1, step = n / size;
    for (let start = 0; start < n; start += size) {
      for (let k = 0, w = 0; k < half; k++, w += step) {
        const a = start + k, b = a + half;
        const wr = cos[w], wi = sign * sin[w];
        const xr = re[b] * wr - im[b] * wi, xi = re[b] * wi + im[b] * wr;
        re[b] = re[a] - xr; im[b] = im[a] - xi;
        re[a] += xr; im[a] += xi;
      }
    }
  }
}

// --- the hall ---------------------------------------------------------------------------------

const halls = new Map();
// The impulse response at a render's sample rate, split into blocks and
// transformed once: [{re, im}] per block, left channel in the real part of
// the inverse and right in the imaginary part (see convolveHall).
function hall(sampleRate) {
  if (!halls.has(sampleRate)) {
    const bytes = readFileSync(HALL);
    const wav = parseWav(bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength));
    const [left, right] = wav.channels.map(channel => wav.sampleRate === sampleRate ? channel : resample(channel, wav.sampleRate, sampleRate));
    const parts = Math.ceil(left.length / BLOCK), spectra = [];
    for (let p = 0; p < parts; p++) {
      // H = HL + i·HR: the transforms of two real responses in one complex one.
      const re = new Float64Array(SIZE), im = new Float64Array(SIZE);
      for (let i = 0; i < BLOCK && p * BLOCK + i < left.length; i++) { re[i] = left[p * BLOCK + i]; im[i] = right[p * BLOCK + i]; }
      fft(re, im);
      spectra.push({ re, im });
    }
    halls.set(sampleRate, spectra);
  }
  return halls.get(sampleRate);
}

/** Adds the hall's response to the mono `send` (times `gain`) into the stereo
 * channels. The tail stops at the end of the channels. */
export function convolveHall(send, channels, sampleRate, gain) {
  if (!(gain > 0)) return;
  const spectra = hall(sampleRate), parts = spectra.length, n = send.length;
  // Transforms of the latest input blocks, newest first.
  const history = [];
  const outRe = new Float64Array(SIZE), outIm = new Float64Array(SIZE);
  const carryL = new Float64Array(BLOCK), carryR = new Float64Array(BLOCK);
  const [left, right] = channels;
  const scale = gain / SIZE;
  for (let start = 0; start < n + parts * BLOCK; start += BLOCK) {
    if (start >= n && history.every(h => h === null)) break;
    let input = null;
    if (start < n) {
      const re = new Float64Array(SIZE), im = new Float64Array(SIZE);
      let any = false;
      for (let i = 0; i < BLOCK && start + i < n; i++) { const v = send[start + i]; re[i] = v; if (v !== 0) any = true; }
      if (any) { fft(re, im); input = { re, im }; }
    }
    history.unshift(input);
    if (history.length > parts) history.pop();
    // Y = Σ X_k · H_k. X is the transform of a real block, so each product
    // keeps HL and HR apart: the inverse gives left in re and right in im.
    outRe.fill(0); outIm.fill(0);
    let any = false;
    for (let k = 0; k < history.length; k++) {
      const x = history[k];
      if (!x) continue;
      any = true;
      const h = spectra[k], xr = x.re, xi = x.im, hr = h.re, hi = h.im;
      for (let i = 0; i < SIZE; i++) {
        outRe[i] += xr[i] * hr[i] - xi[i] * hi[i];
        outIm[i] += xr[i] * hi[i] + xi[i] * hr[i];
      }
    }
    if (any) fft(outRe, outIm, true);
    for (let i = 0; i < BLOCK; i++) {
      const frame = start + i;
      const l = (any ? outRe[i] * scale : 0) + carryL[i], r = (any ? outIm[i] * scale : 0) + carryR[i];
      if (frame < left.length) { left[frame] += l; right[frame] += r; }
      carryL[i] = any ? outRe[BLOCK + i] * scale : 0;
      carryR[i] = any ? outIm[BLOCK + i] * scale : 0;
    }
  }
}
